158		if err != nil {
159			return nil, err
160		}
161		db, err := sql.Open(sqlitedriver.Name, path)
162		if err != nil {
163			return nil, err
164		}
165		db.SetMaxOpenConns(1)
166		for _, pragma := range []string{"PRAGMA busy_timeout=5000;", "PRAGMA journal_mode=WAL;"} {
167			if _, err := db.Exec(pragma); err != nil {
168				db.Close()
169				return nil, err
170			}
171		}
172		if historyFTSFreshIdentity(db, identity) {
173			return db, nil
174		}
175		db.Close()
176		return nil, nil
177	}
