250	// writer. A tombstone cannot linearize between the last policy check and the
251	// first response byte because both use the same per-Brain write lock.
252	func (s *Server) privacyResponseMiddleware(next http.Handler) http.Handler {
253		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
254			if !strings.HasPrefix(r.URL.Path, "/api/") {
255				next.ServeHTTP(w, r)
256				return
257			}
258			policy, err := brainstore.CaptureRetrievalPrivacyPolicy(s.BrainDir)
259			if err != nil {
260				http.Error(w, err.Error(), http.StatusServiceUnavailable)
261				return
262			}
263			buffered := &bufferedVizResponse{header: make(http.Header)}
264			next.ServeHTTP(buffered, r)
265			status := buffered.status
266			if status == 0 {
267				status = http.StatusOK
268			}
269			err = s.Deps.CommitRetrievalResponse([]brainstore.RetrievalPrivacyPolicy{policy}, func() error {
270				copyHTTPHeaders(w.Header(), buffered.header)
271				w.WriteHeader(status)
272				if buffered.body.Len() == 0 {
273					return nil
274				}
275				n, writeErr := w.Write(buffered.body.Bytes())

