38	//
39	// ProposedBy carries cross-member ROUTING: the id of the member whose sync raised
40	// the proposal (the "candidate" side of the conflict). The merge core never sets it
41	// — it is stamped by the cross-member sync layer (internal/factsync), which knows
42	// who is syncing — so a proposal a team member opens is attributable and routable.
43	// It is omitempty and ignored by the single-user local review flow, keeping the
44	// on-disk format backward compatible.
45	type Proposal struct {
46		Action      string  `json:"action"` // "merge" | "supersede"
47		CandidateID string  `json:"candidate_id"`
48		TargetID    string  `json:"target_id"`
49		Confidence  float64 `json:"confidence"`
50		Branch      string  `json:"branch,omitempty"`
51		ProposedBy  string  `json:"proposed_by,omitempty"`
52	}
53	
54	// ApplyActions folds a chronological sequence of agent actions into an
55	// active fact set, returning the updated set and any proposals that need human
56	// review. Actions are applied in order so each one sees the set as it stood at
57	// that point — a --force rebuild replays the same order and reconstructs the
58	// identical chain.
59	//
60	// High-confidence merge consolidates the candidate's provenance into the target
61	// and drops the candidate. High-confidence supersede marks the target
62	// superseded (never deleted) and adds the candidate as the active replacement.
63	// Below threshold, both facts stay active, are cross-linked, and a proposal is
64	// queued. An action whose target is unknown or is the candidate itself degrades
65	// to `new`.
66	func ApplyActions(active []Record, actions []Action, threshold float64, now time.Time) ([]Record, []Proposal) {
67		var proposals []Proposal
68		for _, action := range actions {
69			candidate := action.Candidate
70			if action.Confidence > 0 {
71				candidate.Confidence = renderConfidence(action.Confidence)
72			}
73			switch action.Kind {
74			case ActionMerge, ActionSupersede:
75				ti := IndexOf(active, action.TargetID)
76				if ti < 0 || action.TargetID == candidate.ID {
77					active = Upsert(active, candidate) // unknown/self target: keep as new
78					continue
79				}
80				if action.Confidence < threshold {
81					// Low confidence: never silently rewrite. Keep both active,
82					// cross-link them, and queue the decision for review.
83					candidate.RelatedIDs = appendUniqueString(candidate.RelatedIDs, active[ti].ID)
84					active[ti].RelatedIDs = appendUniqueString(active[ti].RelatedIDs, candidate.ID)
85					active = Upsert(active, candidate)
86					proposals = append(proposals, Proposal{
87						Action:      action.Kind,
88						CandidateID: candidate.ID,
89						TargetID:    action.TargetID,
90						Confidence:  action.Confidence,
91						Branch:      candidate.Branch,
92					})
93					continue
94				}
95				if action.Kind == ActionMerge {
96					// Same meaning: consolidate provenance into the target and drop
97					// the candidate. The target's text (the earlier phrasing) wins.
98					active[ti].Provenance = UnionAnchors(active[ti].Provenance, candidate.Provenance)
99					if now.After(active[ti].UpdatedAt) {
100						active[ti].UpdatedAt = now
101					}
102					continue
103				}
104				// Supersede: retain the old fact, mark it superseded, and add the
105				// candidate as the active replacement.
106				active[ti].Status = StatusSuperseded
107				active[ti].SupersededBy = candidate.ID
108				active[ti].UpdatedAt = now
109				candidate.RelatedIDs = appendUniqueString(candidate.RelatedIDs, action.TargetID)
110				active = Upsert(active, candidate)
111			default:
112				active = Upsert(active, candidate)
113			}
114		}
115		return active, proposals
116	}
