ensureBranch := func(branch string) {
	if loaded[branch] {
		return
	}
	existing, loadErr := factstore.Load(brainDir, branch)
	if loadErr != nil {
		warnings = append(warnings, fmt.Sprintf("load facts for %s: %v", branch, loadErr))
	}
	baselineByBranch[branch] = cloneDistillFacts(existing)
